const dispatchingResource = new WeakSet()

export const resourceSchema: z.ZodType<FhirJson<FhirResource>> = z
  .custom<FhirJson<FhirResource>>(
    (value) =>
      typeof value === 'object' &&
      value !== null &&
      typeof (value as { resourceType?: unknown }).resourceType === 'string',
    {
      message: 'Expected a FHIR resource carrying a resourceType.',
      abort: true,
    },
  )
  .superRefine((value, ctx) => {
    const modelled = modelledResources[value.resourceType]
    if (modelled === undefined) {
      ctx.addIssue({
        code: 'custom',
        path: ['resourceType'],
        message: 'Resource type is not published by this pinned FHIR release.',
      })
      return
    }
    // JSON cannot describe a resource that contains itself, but an in-memory object can,
    // and re-entering one would recur until the stack ran out.
    if (dispatchingResource.has(value)) return
    dispatchingResource.add(value)
    try {
      const result = modelled.safeParse(value)
      if (result.success) return
      // Re-raised rather than summarised, so a fault inside the resource still names the
      // element that carries it.
      for (const issue of result.error.issues) ctx.addIssue({ ...issue })
    } finally {
      dispatchingResource.delete(value)
    }
  })

